import {getSession} from '../../../../lib/session';import {getDb} from '../../../../lib/db';import {jsonError,jsonOk} from '../../../../lib/http';
export async function GET(){const user=await getSession();if(!user)return jsonError('Please sign in.',401);if(user.role!=='VENDOR')return jsonError('Vendor access required.',403);try{const db=getDb();const [rows]=await db.execute('SELECT w.available_balance,w.pending_balance FROM wallets w JOIN vendors v ON v.id=w.vendor_id WHERE v.user_id=? LIMIT 1',[user.id]);return jsonOk({wallet:rows[0]||{available_balance:0,pending_balance:0}});}catch(e){console.error('Vendor wallet error:',e);return jsonError('Could not load wallet.',500);}}
